#use "topfind";;
#require "bos.setup,yojson";;
open Bos
open Yojson.Basic.Util
let get = function Ok x -> x | Error (`Msg e) -> failwith e
let s x = `String x
let strings xs = `List (List.map s xs)
let str k j = member k j |> to_string
let arr k j = member k j |> to_list
let assoc fields = `Assoc fields
let put fields j = match j with `Assoc old -> `Assoc (fields @ List.filter (fun (k,_) -> not (List.mem_assoc k fields)) old) | _ -> failwith "object required"
let read p = Yojson.Basic.from_file p
let write p text = get (OS.File.write (Fpath.v p) text)
let json p j = write p (Yojson.Basic.pretty_to_string j ^ "\n")
let sha p = let out,(_,rc) = get (OS.Cmd.run_out (Cmd.of_list ["sha256sum";p]) |> OS.Cmd.out_string) in if rc <> `Exited 0 then failwith ("hash failed: "^p); String.sub out 0 64
let prefix = "20260906-1655"
let base_path = "governance/planning/20260906-0817-uos-full-implementation-backlog.json"
let additions_path = "governance/planning/"^prefix^"-uos-execution-additions.json"
