let detail_path = "docs/design/"^prefix^"-uos-sa-plan-work-items.md"
let journal_path = "docs/journal/"^prefix^"-uos-sa-plan-execution-planning-journal.md"
let receipt_path = "governance/sources/"^prefix^"-uos-sa-plan-registration-receipt.json"
let plan_id = "uos/full-implementation/"^prefix
let db = "/home/an/NAS-setup/uos/var/sa-plan/uos.sqlite3"
let root = "/home/an/NAS-setup/uos"
